commit;
select codigo,nombre,(select count(*) from diagnosticos d where d.paciente_id=p.id) as dx,(select count(*) from recetas r where r.paciente_id=p.id) as recetas,(select count(*) from controles c where c.paciente_id=p.id) as controles from pacientes p where codigo like 'VIT-%' order by codigo;
