insert into pacientes (id,codigo,nombre,rut,fecha_nacimiento,sexo_biologico,genero,direccion,comuna,ciudad,email,telefono,prevision,ocupacion,preferencia_atencion,tipo_consulta,fecha_ingreso,profesional,estado,proximo_control,ultimo_registro,motivo_consulta,prioridades,narrativa_clinica,notas_calidad_dato) values ('00000001-0000-4000-8000-000000000000','VIT-0001','Licet Carolina Gallegos Hernández','16.736.069-6','1988-03-07','femenino',null,null,null,null,null,null,null,null,null,'medicina_cannabica','2025-12-30','Dra. Valeria Alarcón Kunakov','activo','2026-06-30','2025-12-30','Medicina Cannábica. Dolor de espalda y manejo de ansiedad. Acudió previamente a TMT sin exámenes.','Mantener la actividad física recién iniciada y recuperar energía.','Persona motivada, con actividad física iniciada día por medio (en acción) y herramientas de manejo del estrés. Refiere falta de energía constante que afecta el ánimo. Hiperlaxitud. Sospecha componente ergonómico del dolor por su trabajo (curaciones y procedimientos), aunque el dolor persiste fuera del trabajo.','RUT aparece como 16736069-6 y como 16.736-069-6 (formato con puntos malformado); normalizado a 16.736.069-6, a confirmar. Ficha actualizada en clinicas.cl el 14/10/2026.');
