insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000001-c0c0-4000-8000-000000000000','00000001-0000-4000-8000-000000000000','2025-12-30','ingreso','virtual','Dolor de espalda; previamente consultó TMT sin exámenes. Falta de energía constante que afecta el ánimo. Inició actividad física día por medio, motivada, aún no percibe el aumento de energía que le anticiparon.',null,'Lumbalgia crónica + TAG. Buena activación. Cuenta con herramientas de manejo del estrés y respeta sus tiempos.',array['Receta magistral de Cannabis (1,5 g/día, ratio 2:1–5:1) por 6 meses, en recemed.cl','Mantener actividad física; educación motivacional breve','Incrementar proteína vegetal (leguminosas, cereales integrales)','Educación en ley cannábica y protección al consumidor','Próximo control en 6 meses, o antes'],array[]::text[],array['Alta motivación','Herramientas propias de manejo del estrés','Compañía de mascotas'],array[]::text[],array['Ley cannábica y protección al consumidor','Beneficios de las leguminosas'],'Mantener actividad física y plan alimentario; reevaluar energía y dolor en 6 meses.','2026-06-30');
