insert into pacientes (id,codigo,nombre,rut,fecha_nacimiento,sexo_biologico,genero,direccion,comuna,ciudad,email,telefono,prevision,ocupacion,preferencia_atencion,tipo_consulta,fecha_ingreso,profesional,estado,proximo_control,ultimo_registro,motivo_consulta,prioridades,narrativa_clinica,notas_calidad_dato) values ('00000002-0000-4000-8000-000000000000','VIT-0002','Domingo Antonio Chiguay Pinto','18.799.411-K','1995-01-16','masculino',null,'Reumen 1865','Antofagasta',null,'domingo.negocio@gmail.com','89136844',null,null,null,'medicina_cannabica','2026-04-10','Dra. Valeria Alarcón Kunakov','activo','2026-10-31','2026-04-10','Malestar emocional por trastorno mixto ansioso-depresivo, posterior a trabajo en cuarto turno 2x2 (turnos noche). Insomnio y, en ocasiones, dolor torácico irradiado al cuello (recibió licencia e inició ansiolíticos).','Volver a trabajar sin turnos (idealmente Lu–Vi, mañanas, sin jornadas extensas); mantener el buen automanejo.','Cuadro gatillado por turnos nocturnos. Actualmente cesante, dándose un tiempo; niega anhedonia. Buen automanejo; apoyo familiar. Usa cannabis desde hace 10 años (inicio recreativo, hoy tranquilizante/relajación/meditación y para dormir).','DISCREPANCIA DE FECHA: encabezado de ingreso 10/04/2026, pero el certificado dice 10 de Marzo de 2026. Se usa 10/04/2026. Ratio flores: ingreso 1:3–4, certificado 1:5 (a confirmar). Próximo control pasó de 1 mes (ingreso) a 6 meses (control 23/04).');
