insert into medicamentos (paciente_id,nombre,dosis,frecuencia,indicacion,estado,notas) values ('00000002-0000-4000-8000-000000000000','Clotiazepam','10 mg','SOS','Ansiolítico ante gatillantes (agorafobia, delantal blanco), ≤2 v/sem','sos','Control 23/04: solo lo usó 1 vez tras iniciar las gotas.');
insert into cannabis_anamnesis (paciente_id,anios_uso,inicio_motivo,uso_actual,frecuencia,cantidad,usa_aceite,objetivo_terapeutico,notas) values ('00000002-0000-4000-8000-000000000000','10 años (THC)','recreativo','Tranquilizante; relajación y meditación, tarde/noche para dormir.','Ocasional, 3–4 v/semana','4 g/semana',false,'Ansiedad, crisis por gatillantes (aglomeraciones), insomnio','Control 23/04: disminuyó uso recreacional. Luego se incorporan aceite y trociscos.');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000002-c0c0-4000-8000-000000000000','00000002-0000-4000-8000-000000000000','2026-04-10','ingreso','virtual','Malestar emocional posterior a cuarto turno 2x2 (turnos noche); insomnio y dolor torácico que motivó licencia y ansiolíticos. Cesante, dándose un tiempo; niega anhedonia. Piensa volver sin turnos (Lu–Vi, mañanas). Conversó con su familia. Buen automanejo.',null,'Trastorno mixto ansioso-depresivo + pánico con agorafobia. Cannabis de larga data con viraje a uso terapéutico. Plan: optimizar terapia con miras a desprescribir BZD y luego estabilizadores.',array['Flores 1 g/día (1:3–4; cert. 1:5) por 6 meses','Solución para vaporización vespertina SOS (2 caladas máx.)','Aceite sublingual 3 gotas vespertinas, titular al alza','Iniciar psicología si le hace sentido; mantener medicación','Intención de desprescribir BZD y luego estabilizadores','Educación Ley 20.000','Próximo control en 1 mes'],array[]::text[],array['Apoyo familiar','Buen automanejo','Motivación por reorganizar su vida laboral'],array['Turnos nocturnos como gatillante','Aglomeraciones gatillan crisis'],array['Ley 20.000; derechos y deberes del usuario'],'Optimizar terapia; evaluar desprescripción de BZD.','2026-05-10');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000002-c0c0-4000-8000-000000000001','00000002-0000-4000-8000-000000000000','2026-04-23','control','whatsapp','Buena respuesta de crisis y sueño. Clotiazepam solo 1 vez tras iniciar las gotas. Se le olvida el antidepresivo. Disminuyó uso recreacional. Sigue buscando trabajo, tranquilo.',null,'Buena evolución sintomática con la terapia cannábica. Se inicia desprescripción de Escitalopram y se amplían formulaciones (trociscos).',array['Repetir recetas: flores x2, vaporizador x3, aceite x3, trociscos x3','Entregar dato de Bioformula','Iniciar desprescripción de Escitalopram','Control en 6 meses (Oct–Nov 2026)'],array[]::text[],array['Buena respuesta a la terapia','Menor uso de BZD','Menor uso recreacional'],array[]::text[],array[]::text[],'Desprescripción de Escitalopram; mantener esquema; control en 6 meses.','2026-10-31');
