insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000003-c0c0-4000-8000-000000000000','00000003-0000-4000-8000-000000000000','2025-02-13','ingreso','virtual','Cannabis terapéutico por dolor crónico de lesiones deportivas. Alimentación balanceada omnívora. Trabajo físico (mantención de césped ANFP); bici diaria; hockey patines 4 d/sem.','Dolor crónico de tobillos; secuelas de politraumatismos.','Artralgia + politraumatismos + insomnio orgánico. Muy activo, buen capital de movimiento.',array['Receta Cannabis 1:1, 3 g/día, por 3 meses, en recemed.cl','Kinesioterapia Motora','Incrementar alimentos basados en plantas (antiinflamatorio)','Próximo control en 3 meses: lunes 12/05/2025'],array[]::text[],array['Alta actividad física','Trabajo físico activo','Deporte de equipo (hockey)'],array[]::text[],array['Protección legal del consumidor'],'Dolor con cannabis + kinesioterapia + alimentación antiinflamatoria.','2025-05-12');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000003-c0c0-4000-8000-000000000001','00000003-0000-4000-8000-000000000000','2025-12-01','control','virtual','Reporta estrés: siniestro automovilístico reciente, recuperándose emocionalmente.','Dolor crónico: EVA mínimo 4, máximo 7. Buena respuesta a cannabis inhalado nocturno.','Buena analgesia nocturna. Nuevo estresor vital con impacto emocional: se agrega TEPT.',array['Mantener Cannabis 1:1, 3 g/día, 90 g/mes, 3 meses (270 g)','Actualizar dirección en recemed'],array[]::text[],array[]::text[],array['Siniestro automovilístico reciente'],array[]::text[],'Reforzar manejo del estrés; mantener terapia.',null);
