insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000004-c0c0-4000-8000-000000000000','00000004-0000-4000-8000-000000000000','2026-08-04','ingreso','virtual','Ansiedad, insomnio y artralgias recurrentes (EVA 1–4). Accede a uso nocturno de trociscos + vaporizaciones rosin.',null,'Trastorno mixto ansioso depresivo + insomnio no orgánico + dolor crónico secundario. Usuario de larga data; se ofrece recetario magistral.',array['Flores/RSO 9:1, 2 g vespertino-nocturnos/día, 6 meses (o rosin equivalente)','Trociscos THC 18 + CBD 2 mg, 1 c/24 h nocturno, 6 meses','Evitar conducir bajo efectos de THC','Incrementar alimentos basados en plantas (eje intestino-microbiota-cerebro)','Vida en movimiento, higiene del sueño, manejo del estrés (mindfulness), relaciones saludables','Educación Ley 20.000 y Ley 21.817','Próximo control en 3 meses'],array[]::text[],array[]::text[],array['No realiza actividad física estructurada'],array['Ley 20.000 y Ley 21.817; derechos y deberes','Principios de Medicina del Estilo de Vida'],'Evaluar respuesta a trociscos + rosin nocturno en 3 meses.','2026-11-04');
