insert into pacientes (id,codigo,nombre,rut,fecha_nacimiento,sexo_biologico,genero,direccion,comuna,ciudad,email,telefono,prevision,ocupacion,preferencia_atencion,tipo_consulta,fecha_ingreso,profesional,estado,proximo_control,ultimo_registro,motivo_consulta,prioridades,narrativa_clinica,notas_calidad_dato) values ('00000005-0000-4000-8000-000000000000','VIT-0005','Camila Alejandra Llautureo Ardabán','19.189.181-3','1995-12-27','femenino',null,'Reumen 1865, depto 6','Antofagasta',null,'llcamy@hotmail.com','62187126',null,'Químico Farmacéutico',null,'medicina_cannabica','2026-03-04','Dra. Valeria Alarcón Kunakov','activo','2026-10-31','2026-03-04','Dolor crónico (EVA 4–8), ansiedad, pánico y descompensaciones asociadas a disautonomía; busca mejorar sueño, dolor y ansiedad.','Mejorar el sueño, el dolor y la ansiedad laboral; reducir uso de benzodiacepinas.','Químico farmacéutico en atención de público. En controles con Psiquiatra y Cardiólogo. Disautonomía con descompensaciones (dolor en cadera/piernas, epistaxis por cambios de presión). Ansiedad y pánico; espacios reducidos y aglomeraciones gatillan descompensación, desorientación y fatiga muscular. Usuaria de cannabis hace 10 años.','RUT figura como 19.189.181.3 en el certificado (formato con puntos malformado); normalizado a 19.189.181-3, a confirmar. El certificado dice «Con fecha de del año 2026» (día faltante). DISCREPANCIA: el acuerdo del control 23/04 indica trociscos THC:CBD 5:1, pero la receta de trociscos emitida es 10:10 mg (1:1). Gomitas de THC 30 mg se mencionan (buena respuesta SOS diurno) pero no se formalizan como receta separada.');
