insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000005-c0c0-4000-8000-000000000000','00000005-0000-4000-8000-000000000000','2026-03-04','ingreso','virtual','La mayoría de los días despierta con dolor (cadera/piernas) por descompensaciones; epistaxis 2–3 v/sem por cambios de PA. Ansiedad por el trabajo (atención de público), con temblores y cefalea. Pensamientos depresivos sin ideación suicida actual. Dolor torácico opresor cuando está nerviosa o estresada. Espacios reducidos y aglomeraciones producen descompensación, desorientación y fatiga muscular. A veces problemas para dormir.',null,'Cuadro ansioso-depresivo con pánico, sobre disautonomía y dolor crónico. Se educa en preferir vaporización e iniciar gotas sublinguales.',array['Flores 1:1, 2 g/día ante descompensación (o vaporización de extracto THC 250/CBD 250)','Aceite sublingual THC 10/CBD 10 mg/ml, 3 gotas nocturnas, titular al alza','Mantener controles con especialistas y medicación; evaluar desprescripción de BZD en el próximo control','Próximo control en 1 mes'],array[]::text[],array['Formación en farmacia (adherencia)'],array['Trabajo de atención de público como estresor'],array['Preferir vaporización; uso de gotas'],'Evaluar respuesta e iniciar desprescripción de BZD.','2026-04-04');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000005-c0c0-4000-8000-000000000001','00000005-0000-4000-8000-000000000000','2026-04-23','control','whatsapp','Excelente respuesta en sueño, actualmente sin insomnio. Menor uso de BZD: bajó a 10–12 veces/mes (antes diario). Probó gomita de THC 30 mg en situación SOS diurna con buena respuesta.',null,'Muy buena evolución del sueño y reducción de BZD. Se incorpora formato SOS diurno (gomita/trocisco).',array['Trociscos THC:CBD (acuerdo 5:1; receta emitida 10:10 mg)','Recetas mensuales de retenidos (aceite, trociscos, vaporizador) x3','Repetir receta de flores x2 (dispensario sin stock)','Enviar dato de Bioformula','Control en 3 meses'],array[]::text[],array['Buena respuesta en sueño','Reducción de benzodiacepinas'],array[]::text[],array[]::text[],'Mantener esquema; formalizar SOS diurno; control en 3 meses.','2026-10-31');
