insert into pacientes (id,codigo,nombre,rut,fecha_nacimiento,sexo_biologico,genero,direccion,comuna,ciudad,email,telefono,prevision,ocupacion,preferencia_atencion,tipo_consulta,fecha_ingreso,profesional,estado,proximo_control,ultimo_registro,motivo_consulta,prioridades,narrativa_clinica,notas_calidad_dato) values ('00000007-0000-4000-8000-000000000000','VIT-0007','Diego Javier González Echeverría','17.706.673-7','1991-01-23','masculino','masculino','La Cañada 6690, La Reina',null,null,'diegoxkf@gmail.com','988647785','ISAPRE','Tecnólogo médico, subgerencia clínica en Centro Radioterápico',null,'medicina_cannabica','2025-03-10','Dra. Valeria Alarcón Kunakov','activo','2027-01-21','2025-03-10','Dolor osteomuscular crónico secundario y manejo del estrés por sobrecarga laboral (trabajo en oncología).','Manejar el dolor del tren superior y la carga de estrés; mejorar el sueño.','Tecnólogo médico en radioterapia; convive con su pareja Josefina. Dieta vegetariana muy cuidada (B12 y omegas veganos, evita ultraprocesados). Sedentario los últimos 2 años pero con movimiento laboral (camina ~8 h) y jardinería casi diaria (patio 350 m²); medita 2 v/sem. Usuario de cannabis hace 14 años, diario hace 12; usa resina/live resin/BHO. Dolor del tren superior (cuello/hombros) que maneja con masajes, calor y cannabis vespertino.','Dosis y totales de flores varían entre secciones de la ficha (2→1→4 g/día; 60/90/120 g/mes; 270/360/720 g). Ratio pasó de 10:1 a 9:1. Reporta uso recreativo de psilocibina y LSD ~1 vez al año (control 01/12/2025). Se registran los valores tal como aparecen; confirmar la receta vigente.');
