insert into cannabis_anamnesis (paciente_id,anios_uso,inicio_motivo,uso_actual,frecuencia,cantidad,usa_aceite,objetivo_terapeutico,notas) values ('00000007-0000-4000-8000-000000000000','14 años (diario hace 12)','recreativo','Analgésico y relajante, generalmente de noche tras el trabajo.','Diario','1 g/día (4 g/semana en controles)',true,'Dolor osteomuscular y estrés','Usa resina, live resin o BHO (extracto).');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000007-c0c0-4000-8000-000000000000','00000007-0000-4000-8000-000000000000','2025-03-10','ingreso','virtual','Estrés por sobrecarga laboral, sumado a la carga de trabajar en oncología. Dolor de musculatura del tren superior (cuello y hombros); se hace masajes, aplica calor y baños de agua caliente; usa cannabis en las tardes. Dieta vegetariana rica en frutas y legumbres, B12 y omegas. Sedentario los últimos 2 años; camina mucho en el trabajo; jardinería casi diaria; meditación 2 v/sem.','Dolor del tren superior (cuello/hombros).','Dolor osteomuscular crónico + trastorno ansioso + estrés agudo recurrente sobre sobrecarga laboral.',array['Flores 10:1, 2 g/día o extracción equivalente, 6 meses','Mantener hábitos saludables (dieta vegetariana con B12, manejo del estrés, masajes)','Optimizar actividad física: musculación ≥1 v/sem, carga, 20 min + 10 de elongación, grandes grupos','Kinesioterapia Motora y de Rehabilitación','Próximo control en 6 meses (sugerido 08/09/2025)'],array[]::text[],array['Dieta vegetariana cuidada','Meditación','Jardinería diaria','Apoyo de pareja'],array['Sobrecarga laboral','Carga emocional de oncología'],array[]::text[],'Analgesia con cannabis + optimizar actividad física + mantener hábitos protectores.','2025-09-08');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000007-c0c0-4000-8000-000000000001','00000007-0000-4000-8000-000000000000','2025-12-01','control','virtual','Reporta dolor en brazo derecho y estrés con dificultades para dormir (insomnio de conciliación). Usa cannabis como analgésico/relajante, de noche tras el trabajo. Uso recreativo de psilocibina y LSD ~1 v/año.','EVA actual 1–4 (mínimo y máximo).','Buen control del dolor; aparece insomnio de conciliación y estrés sostenido.',array['Flores 10:1, 1 g/día, 30 g/mes, 6 meses (180 g)'],array[]::text[],array[]::text[],array['Insomnio de conciliación'],array[]::text[],'Ajustar dosis; reforzar higiene del sueño.',null);
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000007-c0c0-4000-8000-000000000002','00000007-0000-4000-8000-000000000000','2026-01-13','control','virtual',null,null,'Continúa manejo del dolor y estrés.',array['Flores 10:1, 1 g/día, 30 g/mes, 6 meses (180 g)','Kinesioterapia Motora y de Rehabilitación','Mantener alimentos basados en plantas','Optimizar actividad física (musculación con carga)','Psicoterapia por altas cargas de estrés/cortisol','Educación legal','Próximo control en 6 meses'],array[]::text[],array[]::text[],array[]::text[],array['Ley y protección del consumidor'],'Sumar psicoterapia y actividad física con carga.','2026-07-13');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000007-c0c0-4000-8000-000000000003','00000007-0000-4000-8000-000000000000','2026-07-21','control','virtual','EVA 1–4. Persisten dolor de brazo derecho, estrés e insomnio de conciliación. Cannabis de noche tras el trabajo; 4 g/semana; no usa aceite. Uso recreativo de psilocibina/LSD ~1 v/año.','EVA 1–4.','Se amplían presentaciones (aceite y trociscos) y se sube dosis de flores.',array['Flores 9:1, 4 g/día, 120 g/mes, 6 meses (720 g; o rosin 15–24 g/mes)','Aceite sublingual THC 18/CBD 2 mg/ml, 3 gotas c/12 h','Trociscos THC 18 + CBD 2 mg, 1 c/24 h','Evitar conducir bajo efectos de THC','Incrementar alimentos basados en plantas','Vida en movimiento, higiene del sueño, mindfulness','Educación Ley 20.000 y 21.817','Control en 6 meses (Enero 2027)'],array[]::text[],array[]::text[],array[]::text[],array['Ley 20.000 y 21.817'],'Mantener esquema ampliado; control en 6 meses.','2027-01-21');
