insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000008-c0c0-4000-8000-000000000000','00000008-0000-4000-8000-000000000000','2026-07-21','ingreso','virtual','Dolor lumbar crónico (EVA 1–4), uso de cannabis vaporizada nocturna para alivio. Usuario hace 15 años.',null,'Lumbago mecánico + escoliosis + dolor crónico.',array['Flores 3:1, 4 g vespertino-nocturnos/día, 6 meses (o rosin equivalente)','Evitar conducir bajo efectos de THC','Incrementar alimentos basados en plantas (eje intestino-microbiota-cerebro)','Vida en movimiento, higiene del sueño, manejo del estrés (mindfulness), relaciones saludables','Educación Ley 20.000 y 21.817; opciones de adquisición (cultivo, dispensarios, farmacéuticas)','Próximo control (6 meses según acuerdo; 1 mes según certificado)'],array[]::text[],array[]::text[],array[]::text[],array['Ley 20.000 y 21.817','Vías de adquisición y consumo no pirolítico'],'Analgesia con cannabis + principios de Medicina del Estilo de Vida.','2027-01-21');
