insert into pacientes (id,codigo,nombre,rut,fecha_nacimiento,sexo_biologico,genero,direccion,comuna,ciudad,email,telefono,prevision,ocupacion,preferencia_atencion,tipo_consulta,fecha_ingreso,profesional,estado,proximo_control,ultimo_registro,motivo_consulta,prioridades,narrativa_clinica,notas_calidad_dato) values ('00000010-0000-4000-8000-000000000000','VIT-0010','Juan Pablo Hernandez Pavez','18.741.917-4','1987-07-04','masculino',null,'Av Pacífico 3119','La Serena',null,'jphernandezp@gmail.com','85606798','FONASA','Odontólogo',null,'medicina_cannabica','2026-06-30','Dra. Valeria Alarcón Kunakov','activo','2026-07-30','2026-06-30','Medicina Cannábica por trastorno ansioso-depresivo mixto; uso principal para conciliar el sueño.','Mejorar el sueño y regular emociones; evaluar desprescripción de Lamotrigina.','Odontólogo, en controles con Psiquiatra. Consume cannabis hace 24 años (últimos 12 diario nocturno; antes costaba conciliar el sueño). Prefiere uso nocturno en días de semana (evita diurno por motricidad fina). Desarrolló estrategias de manejo del estrés y percibe que ya no necesita Lamotrigina; atraviesa un periodo de dudas por posible despido.','DISCREPANCIA: control en 1 mes (plan, para evaluar trociscos) vs 6 meses (notas de recetas, Dic–Ene 2027). Consumo de sustancias significativo documentado (tabaco 10/día, cannabis diario, MDMA ~1 v/mes).');
