insert into medicamentos (paciente_id,nombre,dosis,frecuencia,indicacion,estado,notas) values ('00000010-0000-4000-8000-000000000000','Lamotrigina','200 mg','en la mañana','Estabilizador del ánimo','activo','Percibe que ya no la necesita; consultará al especialista. Se educa en que la terapia cannábica puede apoyar la desprescripción.');
