insert into cannabis_anamnesis (paciente_id,anios_uso,inicio_motivo,uso_actual,frecuencia,cantidad,usa_aceite,objetivo_terapeutico,notas) values ('00000010-0000-4000-8000-000000000000','24 años (diario nocturno hace 12)','recreativo','Principalmente para conciliar el sueño; diurno y nocturno los fines de semana; ayuda a regular emociones. Evita diurno en semana por motricidad fina (odontólogo).','Diario (nocturno)','8 g/semana',false,'Sueño, regulación emocional','Prefiere uso nocturno en días de semana.');
insert into controles (id,paciente_id,fecha,tipo,canal,subjetivo,objetivo,evaluacion,acuerdos,recaidas,facilitadores,barreras_nuevas,educacion,proxima_accion,proximo_control) values ('00000010-c0c0-4000-8000-000000000000','00000010-0000-4000-8000-000000000000','2026-06-30','ingreso','virtual','Ansiedad constante. Refiere estrategias personales de manejo del estrés/ansiedad y percibe que ya no necesita Lamotrigina, aunque atraviesa dudas por posible despido; consultará al especialista. Usa cannabis para conciliar el sueño; nocturno en semana (evita diurno por motricidad fina).',null,'Trastorno mixto ansioso-depresivo + TAG. Buen automanejo; plan de evaluar desprescripción de estabilizador del ánimo.',array['Flores 9:1, 2 g desde las 18–20 h hasta dormir, 6 meses (360 g)','Trociscos THC 18 + CBD 2 mg, 1 c/24 h nocturno, 6 meses','Incrementar alimentos basados en plantas','Vida en movimiento, higiene del sueño, mindfulness, relaciones saludables','Iniciar psicología si le hace sentido; mantener medicación; evaluar desprescripción de estabilizador','Contacto con Biofórmula para la receta de trociscos','Educación Ley 20.000','Próximo control en 1 mes (evaluar trociscos)'],array[]::text[],array['Estrategias personales de manejo del estrés','En control con psiquiatría'],array['Posible despido (incertidumbre laboral)'],array['Ley 20.000; derechos y deberes','Principios de Medicina del Estilo de Vida'],'Evaluar respuesta a trociscos; valorar desprescripción de Lamotrigina con el especialista.','2026-07-30');
