insert into recetas (paciente_id,control_id,fecha,tipo_formulacion,descripcion,ratio_thc_cbd,thc_mg_ml,cbd_mg_ml,via,posologia,dosis_diaria,total_mensual,duracion_meses,total_receta,diagnosticos_asociados,estado) values ('00000010-0000-4000-8000-000000000000','00000010-c0c0-4000-8000-000000000000','2026-06-30','trociscos','Trociscos THC 18 + CBD 2 mg, 1 c/24 h nocturno (SOS lento).','18:2',null,null,'oral','1 c/24 h nocturno','1 trocisco','30 trociscos',6,'180 trociscos','T. Mixto Ansioso Depresivo; TAG','vigente');
